                r += 1
            if color != bg and r - start >= 2:
                bars.append(("vertical", edge, start, r - 1, color))

    pairs = []
    for i, a in enumerate(bars):
        for b in bars[i + 1:]:
            if a[0] != b[0] or a[4] != b[4]:
                continue
            if a[0] == "horizontal" and a[1] != b[1]:
                pairs.append((a, b))
            elif a[0] == "vertical" and a[1] != b[1]:
